#!/usr/bin/env python3
"""gen_vectors.py - emits the committed generated files that come from tools/ref/*.py
(design 9.2): src/engine/lj_trig_gen.c (two 4096-point int16 sine/cosine tables, so
nothing in the binary calls sin()) and tests/vectors.h (sACN packet, position, macro
formula and .GS2 layout vectors). Python 3 stdlib only.

    python -I tools/gen_vectors.py            # write both files
    python -I tools/gen_vectors.py --check    # exit 1 when a committed copy differs

The ref scripts are imported by path and only their pure functions are called;
17-position_ref.py's demo() self-check runs every time (no files, no sockets).
"""
import hashlib
import importlib.util
import math
import os
import struct
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
REF = os.path.join(ROOT, "tools", "ref")
OUT_TRIG = os.path.join(ROOT, "src", "engine", "lj_trig_gen.c")
OUT_VEC = os.path.join(ROOT, "tests", "vectors.h")
REFS = ["08-sacn_ref.py", "14-macros_mac_decode.py", "16-gs2_ref.py", "17-position_ref.py"]
N = 4096
SCALE = 32767


def load(name):
    spec = importlib.util.spec_from_file_location(name.replace("-", "_").replace(".py", ""), os.path.join(REF, name))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def banner(tool_inputs):
    lines = ["/* Generated by tools/gen_vectors.py; do not edit. Inputs (sha256, first 16):"]
    for n in tool_inputs:
        h = hashlib.sha256(open(os.path.join(REF, n), "rb").read()).hexdigest()[:16]
        lines.append(" *   tools/ref/%s %s" % (n, h))
    lines.append(" * Regenerate: python -I tools/gen_vectors.py; verify: --check. */")
    return "\n".join(lines) + "\n"


def c_rows(values, per_row=12, fmt="%6d"):
    out = []
    for i in range(0, len(values), per_row):
        out.append("    " + ", ".join(fmt % v for v in values[i:i + per_row]) + ",")
    return "\n".join(out)


def trig_tables():
    """First quadrant from math.sin, the rest by mirroring, so symmetry and the
    cos == sin shifted by N/4 identity hold exactly regardless of libm."""
    q = [int(round(SCALE * math.sin(2 * math.pi * i / N))) for i in range(N // 4 + 1)]
    assert q[0] == 0 and q[N // 4] == SCALE
    sin = [0] * N
    for i in range(N // 4 + 1):
        sin[i] = q[i]
        sin[N // 2 - i] = q[i]
        sin[(N // 2 + i) % N] = -q[i]
        sin[(N - i) % N] = -q[i]
    cos = [sin[(i + N // 4) % N] for i in range(N)]
    return sin, cos


def gen_trig():
    sin, cos = trig_tables()
    return (banner(["17-position_ref.py"]) +
            '#include "engine/lj_trig_gen.h"\n\n'
            "/* round(32767 * sin(2*pi*i/4096)), design 3.6; symmetric by construction. */\n"
            "const int16_t lj_sin4096[4096] = {\n" + c_rows(sin) + "\n};\n\n"
            "const int16_t lj_cos4096[4096] = {\n" + c_rows(cos) + "\n};\n")


def c_bytes(name, data):
    return ("static const uint8_t %s[%d] = {\n" % (name, len(data)) +
            c_rows(list(data), 16, "0x%02x") + "\n};\n")


def gen_vectors(sacn, mac, gs2, pos):
    pos.demo()                                                  # the note's own asserts
    sin, cos = trig_tables()
    out = [banner(REFS), "#ifndef LJ_TESTS_VECTORS_H\n#define LJ_TESTS_VECTORS_H\n#include <stdint.h>\n\n"]

    # --- trig spot values (tie the table to the generator) ---------------------
    out.append("/* lj_sin4096 spot values */\nstatic const struct { int i; int16_t s, c; } lj_vec_trig[] = {\n")
    for i in (0, 1, 256, 512, 1024, 1536, 2048, 2560, 3072, 3584, 4095):
        out.append("    { %d, %d, %d },\n" % (i, sin[i], cos[i]))
    out.append("};\n\n")

    # --- sACN (ANSI E1.31-2018 Appendix B) ---------------------------------------
    cid = bytes.fromhex("ef07c8dd00644401a3a2459ef8e6143e")
    data = sacn.data_packet(cid, "Source_A", 1, bytes(512), 154, sync_addr=7962)
    assert len(data) == 638 and data[16:18] == b"\x72\x6e" and data[38:40] == b"\x72\x58" and data[115:117] == b"\x72\x0b"
    sync = sacn.sync_packet(cid, 7962, 367)
    assert len(sync) == 49 and sync[16:18] == b"\x70\x21"
    disc = sacn.discovery_packet(cid, "Source_A", [3, 1, 2])
    assert len(disc) == 126 and sacn.parse(disc)["universes"] == (1, 2, 3)
    chase = sacn.data_packet(cid, "LJ4EVR", 7962, bytes(range(1, 9)) + bytes(504), 0)
    out.append("/* E1.31 Appendix B: CID ef07c8dd-0064-4401-a3a2-459ef8e6143e, name Source_A, universe 1,\n"
               " * priority 100, sync 7962, seq 154, 512 zero slots. */\n")
    out.append(c_bytes("lj_vec_sacn_cid", cid))
    out.append(c_bytes("lj_vec_sacn_data_b1", data))
    out.append("/* sync packet, sync address 7962, seq 367 */\n" + c_bytes("lj_vec_sacn_sync_b2", sync))
    out.append("/* discovery, universes {3,1,2} -> sorted 1,2,3 */\n" + c_bytes("lj_vec_sacn_disc", disc))
    out.append("/* data packet: name LJ4EVR, universe 7962, seq 0, slots 1..8 = 1..8, rest 0 */\n" + c_bytes("lj_vec_sacn_data_lj", chase))
    term = sacn.data_packet(cid, "LJ4EVR", 7962, bytes(range(1, 9)) + bytes(504), 3, options=sacn.OPT_TERMINATED)
    out.append("/* the same with Options bit 6 Stream_Terminated (6.2.6), seq 3 */\n" + c_bytes("lj_vec_sacn_data_term", term))
    out.append("static const struct { uint16_t universe; const char *addr; } lj_vec_sacn_mcast[] = {\n")
    for u in (1, 2, 255, 256, 7962, 63999, sacn.DISCOVERY_UNIVERSE):
        out.append('    { %d, "%s" },\n' % (u, sacn.multicast_addr(u)))
    out.append("};\n/* 6.7.2 out-of-sequence: new, last, discard */\n"
               "static const struct { uint8_t new_seq, last; int discard; } lj_vec_sacn_oos[] = {\n")
    for new, last in ((5, 5), (250, 255), (6, 5), (0, 200), (100, 110), (0, 255), (236, 0), (235, 0)):
        out.append("    { %d, %d, %d },\n" % (new, last, int(sacn.out_of_sequence(new, last))))
    out.append("};\n\n")

    # --- generic macro formula (14 sec. A.6), no Macros.Mac needed --------------------
    out.append("/* 14 sec. A.6: shape 0 '2*Sine' = round(32640*sin(pi*k/8192)), shape 7 'Sine' = round(32640*sin(2*pi*k/8192)) */\n"
               "static const struct { int k; int16_t two_sine, sine; } lj_vec_gmacro_sine[] = {\n")
    for k in (0, 1, 1024, 2048, 3072, 4096, 6144, 8191):
        out.append("    { %d, %d, %d },\n" % (k, round(32640 * math.sin(math.pi * k / mac.NSAMP)),
                                               round(32640 * math.sin(2 * math.pi * k / mac.NSAMP))))
    out.append("};\n#define LJ_VEC_GMACRO_NSAMP %d\n#define LJ_VEC_GMACRO_SCALE 32640\n\n" % mac.NSAMP)

    # --- .GS2 layout (16) --------------------------------------------------------
    assert gs2.serialize(gs2.parse(bytes(gs2.SIZE))) == bytes(gs2.SIZE)   # parse/serialize agree on the layout
    out.append("#define LJ_VEC_GS2_SIZE %d\n" % gs2.SIZE)
    for k, v in sorted(gs2.SIZES.items()):
        out.append("#define LJ_VEC_GS2_%s_SIZE %d\n" % (k.upper(), v))
    out.append("/* field name, byte offset, kind, count/length (16 sec. LAYOUT) */\n"
               "static const struct { const char *name; uint16_t off; const char *kind; uint16_t n; } lj_vec_gs2_layout[] = {\n")
    for name, off, kind, n in gs2.LAYOUT:
        out.append('    { "%s", 0x%04X, "%s", %d },\n' % (name, off, kind, n))
    out.append("};\n\n")

    # --- position maths (17) -------------------------------------------------------
    out.append("/* 17 sec. 1: readout -> DMX16 -> MSB/LSB, and 8-bit truncate */\n"
               "static const struct { int32_t readout; uint16_t dmx16; uint8_t msb, lsb, dmx8; } lj_vec_pos16[] = {\n")
    for v in (-32768, -16256, -13824, -9984, -1, 0, 1, 17120, 32767):
        d = pos.readout_to_dmx16(v)
        out.append("    { %d, %d, %d, %d, %d },\n" % ((v, d) + pos.split_msb_lsb(d) + (pos.readout_to_dmx8(v),)))
    out.append("};\n/* 17 sec. 5: fan-out offsets, n fixtures, delta bar value */\n"
               "static const struct { int n, delta; int32_t off[8]; } lj_vec_fanout[] = {\n")
    for n, delta in ((5, 95), (5, 86), (4, 95), (2, 10), (8, 127), (3, 1)):
        o = pos.fan_out_offsets(n, delta) + [0] * (8 - n)
        out.append("    { %d, %d, { %s } },\n" % (n, delta, ", ".join(str(x) for x in o)))
    out.append("};\n/* 17 sec. 6: auto delay, linear/circular/segments, n <= 8 */\n"
               "static const struct { const char *style; int n, max_delay, param; uint8_t d[8]; } lj_vec_autodelay[] = {\n")
    for style, n, md, param in (("linear", 4, 256, 0), ("linear", 4, 128, 0), ("linear", 8, 256, 0), ("linear", 8, 64, 0),
                                ("circular", 6, 256, 3), ("segments", 6, 256, 3), ("linear", 1, 256, 0)):
        kw = {"count": param} if style == "circular" else {"segments": param} if style == "segments" else {}
        d = pos.auto_delay(n, style, md, **kw) + [0] * (8 - n)
        out.append('    { "%s", %d, %d, %d, { %s } },\n' % (style, n, md, param, ", ".join(str(x) for x in d)))
    out.append("};\n/* 17 sec. 7: delay byte -> index, effective index (delay then tweak), quantise */\n"
               "static const struct { int idx, delay, tweak, pan_i, tilt_i; } lj_vec_effidx[] = {\n")
    for idx, delay, tweak in ((1024, 64, 0), (0, 64, 0), (0, 0, 10), (4095, 255, 1), (100, 128, 4000)):
        out.append("    { %d, %d, %d, %d, %d },\n" % ((idx, delay, tweak) + pos.effective_index(idx, delay, tweak)))
    out.append("};\nstatic const struct { int idx, step, q; } lj_vec_quant[] = {\n")
    for idx, step in ((0, 512), (511, 512), (512, 512), (4095, 512), (4095, 1), (1000, 300)):
        out.append("    { %d, %d, %d },\n" % (idx, step, pos.quantise(idx, step)))
    out.append("};\n/* 17 sec. 8: cue macro control floor(raw*pct/100) clamped to 127 */\n"
               "static const struct { int raw, pct, out; } lj_vec_scale_raw[] = {\n")
    for raw, pct in ((127, 45), (127, 490), (60, 100), (60, 0), (100, 999), (1, 99), (127, 100)):
        out.append("    { %d, %d, %d },\n" % (raw, pct, pos.scale_raw(raw, pct)))
    out.append("};\n/* 17 sec. 4: the four CHM pan/tilt patch examples, readout (-16256, 17120) */\n"
               "static const struct { int pan_ofs, tilt_ofs, pm, pl, tm, tl; uint8_t out[4]; } lj_vec_patch16[] = {\n")
    p16, t16 = pos.readout_to_dmx16(-16256), pos.readout_to_dmx16(17120)
    for po, to, patch in ((10, 15, None),
                          (10, 15, {"pan_msb": 11, "pan_lsb": 10, "tilt_msb": 16, "tilt_lsb": 15}),
                          (4, 13, {"pan_msb": 4, "pan_lsb": 13, "tilt_msb": 5, "tilt_lsb": 14}),
                          (21, 23, {"pan_msb": 4, "pan_lsb": 13, "tilt_msb": 7, "tilt_lsb": 16})):
        m = pos.patch_16bit(p16, t16, po, to, patch)
        pp = patch or {"pan_msb": po, "pan_lsb": po + 1, "tilt_msb": to, "tilt_lsb": to + 1}
        keys = (pp["pan_msb"], pp["pan_lsb"], pp["tilt_msb"], pp["tilt_lsb"])
        out.append("    { %d, %d, %d, %d, %d, %d, { %s } },\n" % ((po, to) + keys + (", ".join(str(m[k]) for k in keys),)))
    out.append("};\n#define LJ_VEC_POS_HALF %d\n#define LJ_VEC_POS_N_TABLE %d\n#define LJ_VEC_POS_AMP_HALF %d\n"
               % (pos.HALF, pos.N_TABLE, pos.AMP_HALF_RANGE))
    out.append(gen_movement_vectors(pos))          # W3 movement track (appended)
    out.append(gen_artnet_vectors())               # W5 artnet track (appended)
    out.append("\n#endif /* LJ_TESTS_VECTORS_H */\n")
    return "".join(out)



# --- W3 movement track: the movement-macro traces of 17-position_ref.py section 7 (design 10 W3 acceptance 4) -------
def mm_int_tables():
    """The integer pan/tilt tables the engine evaluates (engine/lj_movemacro.c lj_mm_shape) for the six system types,
    built from the lj_trig_gen.c tables with the C's nearest-integer products; gen_movement_vectors ties each entry
    to the oracle's float formulas (17-position_ref.py system_tables): equal, within 2 for the product types 4 and 5."""
    sin, cos = trig_tables()

    def rnd(a, b):                     # nearest; b odd, so never a tie (lj_mm_round)
        return (a + b // 2) // b if a >= 0 else -((-a + b // 2) // b)
    return {1: (cos, sin), 2: (sin, cos), 6: (cos, sin),
            3: ([cos[(2 * i) % N] for i in range(N)], sin),
            4: (cos, [rnd(sin[i] * abs(sin[(2 * i) % N]), SCALE) for i in range(N)]),
            5: (cos, [rnd(sin[i] ** 3, SCALE * SCALE) for i in range(N)])}


def gen_movement_vectors(pos):
    names = {1: "System Ellipse", 2: "System Ellipse 2", 3: "System Cos(2*a),Sin(a)", 4: "System Sin(a)*|Sin(2a)|",
             5: "System Sin(a)^3", 6: "System Stepped Ellipse"}
    tabs = mm_int_tables()
    for ty, (pt, tt) in tabs.items():
        fp, ft = pos.system_tables(names[ty])
        tol = 2 if ty in (4, 5) else 0   # products of rounded tables: 3 * 0.5 + 0.5 at most; the plain sine / cosine types are exact
        assert all(abs(pt[i] - round(SCALE * fp[i])) <= tol and abs(tt[i] - round(SCALE * ft[i])) <= tol for i in range(N)), ty
    out = ["/* 17 sec. 7 movement-macro traces (W3 movement): lj_movemacro_pos(state, macro, NULL, pct, base) == the oracle's\n"
           " * fixture_output(base, macro_offset(tables, effective_index(..), scale_raw(amp, pct), step)) on the engine's\n"
           " * integer tables (gen_vectors.mm_int_tables, each entry within 2 of system_tables * 32767, the sine / cosine ones equal) */\n"
           "static const struct { uint8_t type; uint16_t ip, it; uint8_t amp_pan, amp_tilt; uint16_t pct; uint8_t delay, tweak; uint16_t step;\n"
           "                      int32_t base_pan, base_tilt, pan, tilt; } lj_vec_mm_trace[] = {\n"]
    combos = ((127, 127, 100, 0, 0, 0, 0), (64, 100, 45, 64, 10, 20000, -30000), (1, 3, 490, 255, 0, -32000, 32000),
              (127, 90, 0, 128, 200, 1234, -1234), (100, 127, 999, 16, 64, 32767, -32768), (37, 81, 73, 200, 1, -16256, 17120))
    for ty in range(1, 7):
        pt, tt = tabs[ty]
        tables = ([x / SCALE for x in pt], [x / SCALE for x in tt])
        for idx in (0, 1, 511, 512, 1023, 1024, 1500, 2048, 2730, 3072, 3584, 4095):
            for ap, at, pct, delay, tweak, bp, bt in combos:
                for step in ((1, 512, 300) if ty == 6 else (1,)):
                    ip, it = idx, (idx * 2 + 7) % N              # separate indexes (tilt cycle = 2 x pan: the figure eight)
                    pi = pos.effective_index(ip, delay)[0]
                    ti = pos.effective_index(it, delay, pos.delay_to_index(tweak))[1]
                    o = pos.macro_offset(tables, pi, ti, pos.scale_raw(ap, pct), pos.scale_raw(at, pct), step)
                    p, t = pos.fixture_output((bp, bt), o)
                    out.append("    { %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d },\n" % (ty, ip, it, ap, at, pct, delay, tweak, step, bp, bt, p, t))
    out.append("};\n/* 17 sec. 5 fan_out (centre = home or the middle fixture(s)) and spread; fixture k = index k, order as listed */\n"
               "static const struct { int n, dpan, dtilt, home; int order[6]; int32_t in_pan[6], in_tilt[6], pan[6], tilt[6]; } lj_vec_fan[] = {\n")
    cases = ((3, 95, 86, 1, (0, 1, 2), ((5, 5), (6, 6), (7, 7))),
             (5, 95, 0, 1, (0, 1, 2, 3, 4), ((0, 0),) * 5),
             (5, 40, 20, 0, (4, 3, 2, 1, 0), ((-100, 50), (300, -7), (1001, 2001), (5, 6), (-32768, 32767))),
             (4, 95, 127, 0, (1, 0, 3, 2), ((-3, 3), (8, -8), (20001, -20001), (30000, -30000))),
             (6, 127, 127, 0, (0, 1, 2, 3, 4, 5), ((30000, -30000),) * 6),
             (2, 10, 1, 0, (1, 0), ((-1, 1), (0, 0))))
    for n, dp, dt, home, order, xy in cases:
        r = pos.fan_out({k: xy[k] for k in range(n)}, list(order), dp, dt, center_on_home=bool(home))
        pad = lambda v: ", ".join(str(x) for x in list(v) + [0] * (6 - n))
        out.append("    { %d, %d, %d, %d, { %s }, { %s }, { %s }, { %s }, { %s } },\n" % (
            n, dp, dt, home, pad(order), pad(p for p, _ in xy), pad(t for _, t in xy),
            pad(r[k][0] for k in range(n)), pad(r[k][1] for k in range(n))))
    out.append("};\nstatic const struct { int n, axis; int order[5]; int32_t in[5], out[5]; } lj_vec_spread[] = {\n")
    for n, axis, order, vals in ((3, 0, (0, 1, 2), (-1000, 0, 2000)), (5, 1, (4, 2, 0, 1, 3), (7, -3, 32767, 0, -32768)),
                                 (2, 0, (0, 1), (5, -5)), (4, 0, (3, 2, 1, 0), (0, 0, 0, 100))):
        r = pos.spread({k: (vals[k], vals[k]) for k in range(n)}, list(order), axis)
        pad = lambda v: ", ".join(str(x) for x in list(v) + [0] * (5 - n))
        out.append("    { %d, %d, { %s }, { %s }, { %s } },\n" % (n, axis, pad(order), pad(vals), pad(r[k][axis] for k in range(n))))
    out.append("};\n/* 17 sec. 6 delay_order: mode = enum lj_delay_order (number, number_rev, icon_h, icon_h_rev, icon_v, icon_v_rev); fixture f = index f-1 */\n"
               "static const struct { int mode; int sel[5]; int16_t ix[5], iy[5]; int order[5]; } lj_vec_delay_order[] = {\n")
    icons = {1: (50, 0), 2: (10, 9), 3: (10, 0), 4: (90, 9), 5: (10, 0)}
    for mi, mode in enumerate(("number", "number_rev", "icon_h", "icon_h_rev", "icon_v", "icon_v_rev")):
        sel = [4, 2, 5, 1, 3]
        o = pos.delay_order(sel, mode, icons)
        out.append("    { %d, { %s }, { %s }, { %s }, { %s } },\n" % (
            mi, ", ".join(str(f - 1) for f in sel), ", ".join(str(icons[f][0]) for f in range(1, 6)),
            ", ".join(str(icons[f][1]) for f in range(1, 6)), ", ".join(str(f - 1) for f in o)))
    out.append("};\n/* 17 sec. 7 macro_tick: (idx + dir * incr) mod N */\nstatic const struct { int idx, incr, dir, out; } lj_vec_macro_tick[] = {\n")
    for idx, incr, d in ((4095, 1, 1), (0, 1, -1), (100, 512, 1), (100, 512, -1), (4000, 200, 1)):
        out.append("    { %d, %d, %d, %d },\n" % (idx, incr, d, pos.macro_tick(idx, incr, d)))
    out.append("};\n")
    return "".join(out)

# --- W5 artnet track: Art-Net 4 ArtDmx / ArtPoll reference packets (note 08 s9.2, s9.3; spec p.18-19, p.63) ------------
# An independent struct.pack builder: the C side (io/lj_artnet.c) must reproduce these bytes (tests/io/test_artnet.c).
ARTNET_ID = b"Art-Net\x00"


def artnet_dmx(seq, physical, port_addr, slots):
    assert 1 <= port_addr <= 32767 and len(slots) % 2 == 0 and 2 <= len(slots) <= 512
    return (ARTNET_ID + struct.pack("<H", 0x5000) + bytes((0, 14, seq, physical, port_addr & 0xFF, port_addr >> 8))
            + struct.pack(">H", len(slots)) + bytes(slots))


def artnet_poll(flags=0, diag=0, oem=0x00FF):
    return ARTNET_ID + struct.pack("<H", 0x2000) + bytes((0, 14, flags, diag)) + bytes(4) + struct.pack(">HH", 0, oem)


def gen_artnet_vectors():
    ramp = bytes(i & 0xFF for i in range(512))
    a = artnet_dmx(1, 0, 0x0102, ramp)
    b = artnet_dmx(255, 3, 32767, bytes(255 - (i & 0xFF) for i in range(512)))
    assert len(a) == 530 and a[8:10] == bytes((0x00, 0x50)) and a[14:18] == bytes((0x02, 0x01, 0x02, 0x00))
    poll = artnet_poll()
    assert len(poll) == 22
    return ("/* W5 artnet: ArtDmx seq 1, physical 0 (link 1), Port-Address 0x0102 (Net 1, Sub-Net 0, Universe 2), slot i = i & 255 */\n"
            + c_bytes("lj_vec_artnet_dmx_a", a)
            + "/* ArtDmx seq 255, physical 3 (link 4), Port-Address 32767 (Net 127, SubUni 0xFF), slot i = 255 - (i & 255) */\n"
            + c_bytes("lj_vec_artnet_dmx_b", b)
            + "/* ArtPoll: Flags 0, DiagPriority 0, no target, EstaMan 0, Oem 0x00FF (OemUnknown, PROPOSAL rig W5-ART-7) */\n"
            + c_bytes("lj_vec_artnet_poll", poll))


def main():
    check = "--check" in sys.argv
    if "--shapes" in sys.argv:   # W3 genmacro track: src/engine/lj_shapes_gen.c (shapes_main below)
        return shapes_main(check)
    if "--vtr" in sys.argv:      # W5 dmxin track: src/io/lj_vtr_gen.c (vtr_main below)
        return vtr_main(check)
    if "--audio" in sys.argv:    # W5 audio track: src/io/lj_audio_gen.c + tests/io/audio_vectors.h (audio_main below)
        return audio_main(check)
    mods = {n: load(n) for n in REFS}
    want = {OUT_TRIG: gen_trig(),
            OUT_VEC: gen_vectors(mods["08-sacn_ref.py"], mods["14-macros_mac_decode.py"],
                                 mods["16-gs2_ref.py"], mods["17-position_ref.py"])}
    rc = 0
    for path, text in want.items():
        rel = os.path.relpath(path, ROOT)
        if check:
            have = open(path, encoding="ascii", newline="").read() if os.path.exists(path) else None
            if have != text:
                print("gen_vectors --check: %s differs from the generator output" % rel)
                rc = 1
            else:
                print("gen_vectors --check: %s up to date" % rel)
        else:
            with open(path, "w", encoding="latin-1", newline="\n") as f:
                f.write(text)
            print("wrote %s (%d bytes)" % (rel, len(text)))
    return rc


# ---- W3 genmacro track (appended): --shapes -> src/engine/lj_shapes_gen.c (design 3.6, 9.2; 14 sec. A.6; ME-34) ----------
# The 66 generic-macro shapes in Macros.Mac file order, as OUR integer samples at +-32640 full scale. The sine family is
# exactly round(32640 * sin); every other shape is an authored piecewise definition below. Martin's Macros.Mac is never
# read for emission: with the reference tree present, --shapes --compare prints how far each definition sits from the
# decode of tools/ref/14-macros_mac_decode.py (the table in docs/generated-files.md); CI has no reference and needs none.
OUT_SHAPES = os.path.join(ROOT, "src", "engine", "lj_shapes_gen.c")
GM_N, GM_F = 8192, 32640
GM_NAMES = ["2*Sine", "2*Sine^2", "2*Sine^4", "2*Sine^8", "1/3 Half Sine", "2/3 Half Sine", "2/3 Sine", "Sine", "1/2 Sine",
            "1/3 Sine", "1/4 Sine", "1/8 Sine", "2*Sine^2", "Sine^3", "Sine^5", "Sine^11", "Heartbeat", "Bounce", "Bounce 2",
            "Pulse 8<>", "Pulse 2", "Pulse 4", "Pulse 8", "Sqrt", "Sqrt 1", "Sqrt2", "Sqrt^3", "Sqrt*2", "Sqr", "Log",
            "Inverted Log", "Swapped Log", "2*Triangle", "Triangle", "1/2 Triangle", "1/4 Triangle", "1/8 Triangle",
            "2*SawTooth", "SawTooth", "1/2 SawTooth", "1/4 SawTooth", "1/8 SawTooth", "Square", "2/3 Square", "1/2 Square",
            "1/4 Square", "1/8 Square", "Stair 2", "Stair 4", "Stair 8", "Stair 10", "Stair 16", "Stair 4*2", "Stair 8*2",
            "Stair 10*2", "Stair 16*2", "Swapped Peak", "Swapped Peak^2", "Swapped Peak^4", "Ripple", "Grid", "Cliff 1",
            "Ripple mirror", "Spiky", "Static", "Static 2"]   # 14 sec. A.6 table, verbatim, the duplicate 2*Sine^2 (#1 == #12) kept


def gm_shapes():
    """[(name, [8192 ints])] in file order. Each lambda is the authored definition of one shape, k = 0..8191."""
    N, F, pi, sin = GM_N, GM_F, math.pi, math.sin
    R = lambda v: int(round(F * v))
    hu = lambda v: math.floor(v + 0.5)
    clamp = lambda v: max(-F, min(F, v))
    half = lambda k: sin(pi * k / N)                                     # one hump over the index space
    full = lambda k: sin(2 * pi * k / N)                                 # one period
    part = lambda m: (lambda k: R(sin(2 * pi * k * m / N)) if k * m < N else 0)       # 1/m Sine: a period in the first 1/m
    tri = lambda m: (lambda k, L=N // m: (R(k / (L / 4)) if k < L / 4 else R((L / 2 - k) / (L / 4)) if k < 3 * L / 4
                                          else R((k - L) / (L / 4))) if k < L else 0)
    saw = lambda m: (lambda k, L=N // m: (R(k / (L / 2)) if k < L / 2 else R(-(k - L / 2) / (L / 2))) if k < L else 0)
    sqr = lambda m: (lambda k, L=N // m: (F if k < L / 2 else -F) if k < L else 0)
    pulse = lambda m: (lambda k, L=N // m: int(round(min(F, 32768 * (k // L + 1) / m) * sin(2 * pi * (k % L) / L))))
    sqb = lambda k: min(255, int(round(4 * math.sqrt(k))))               # the 8-bit sqrt rise of 'Sqrt 1' (x 128 = 8.8)
    LOG = 3621.28                                                        # 'Log' = LOG * ln k: 32631 at k = 8191
    lg = lambda k: int(round(LOG * math.log(k))) if k > 0 else 0
    sp = lambda k: 32766.5 * (k / 4096) ** 1.5                           # the Swapped Peak rise
    W = {2: 2730, 4: 1638, 8: 910, 16: 482}                              # stair step widths (the last step takes the rest)
    stair = lambda n: (lambda k: min(F, min(n, k // W[n]) * 32768 // n))
    stair2 = lambda n: (lambda k: min(F, -F + min(n, k // W[n]) * (65536 // n)))
    S102 = [-255, -229, -204, -179, -153, -127, -102, -77, -51, -25, 0, 25, 51, 77, 102, 127, 153, 179, 204, 229, 255]
    alt = lambda k: -1 if k % 1024 <= 512 else 1                         # 'Ripple' / 'Grid': - on 1024j..1024j+512, + between
    P8 = [8192, 16384, 24576, F, F, 24448, 16256, 8064]                 # 'Pulse 8<>' grows then shrinks

    def rmir(k):                                                         # 'Ripple mirror': 16 sin^8 pulses, + growing, - shrinking
        j = k // 512
        a = min(F, 4096 * (j + 1)) if j < 8 else -(F - 4096 * (j - 8))
        return int(round(a * sin(pi * (k % 512) / 512) ** 8))

    def spiky(k):                                                        # 'Spiky': the Swapped Peak swept by a 512-sample ramp
        o = 512 if (k % 1024 == 0 and k) else k % 512
        f = 32768 * (k / 4096) ** 1.5 if k < 4096 else -32768 * ((N - k) / 4096) ** 1.5
        return clamp(int(math.floor(-f * o / 512 + 0.5)))

    def noise(seed, bipolar):                                            # 'Static': 512 held steps of 16 samples, ours (xorshift32)
        x, out = seed, []
        for _ in range(512):
            x ^= (x << 13) & 0xFFFFFFFF
            x ^= x >> 17
            x ^= (x << 5) & 0xFFFFFFFF
            b = (x % 511) - 255 if bipolar else x % 256
            out += [b * 128] * 16
        return out
    st1, st2 = noise(0x4C4A3445, False), noise(0x45565221, True)
    defs = [
        lambda k: R(half(k)), lambda k: R(half(k) ** 2), lambda k: R(half(k) ** 4), lambda k: R(half(k) ** 8),
        lambda k: R(sin(pi * k * 3 / N)) if k * 3 < N else 0,
        lambda k: R(sin(pi * k * 3 / 2 / N)) if k < 2 * N // 3 else 0,
        lambda k: R(sin(3 * pi * k / N)) if k < 2 * N // 3 else 0,
        lambda k: R(full(k)), part(2), part(3), part(4), part(8),
        lambda k: R(half(k) ** 2), lambda k: R(full(k) ** 3), lambda k: R(full(k) ** 5), lambda k: R(full(k) ** 11),
        lambda k: R(sin(pi * k / 2048)) if k < 1324 else R(sin(pi * (k - 1024) / 2048)) if k < 3072 else 0,   # Heartbeat
        lambda k: R(abs(sin(pi * (k / 4621.85) ** 2))) if k < 8000 else 0,                                    # Bounce
        lambda k: R(abs(sin(pi * (k / 3819.05) ** 3))) if k < 8000 else 0,                                    # Bounce 2
        lambda k: int(round(P8[k // 1024] * sin(2 * pi * (k % 1024) / 1024))),
        pulse(2), pulse(4), pulse(8),
        lambda k: int(round(360.96 * math.sqrt(k))),                                                          # Sqrt
        lambda k: sqb(k) * 128 if k <= 4096 else 0,
        lambda k: sqb(k) * 128 if k <= 4096 else 255,
        lambda k: int(round(32660.05 * (k / N) ** 1.5)),                                                      # Sqrt^3
        lambda k: sqb(k) * 128 if k <= 4096 else sqb(N - k) * 128,
        lambda k: R((k / N) ** 2), lg,
        lambda k: F if k <= 100 else F - lg(k - 99),
        lambda k: (lg(2 * k) if k >= 50 else 0) if k <= 4096 else (-lg(2 * (N - k)) if N - k >= 50 else 0),
        lambda k: R(k / 4096 if k < 4096 else (N - k) / 4096),
        lambda k: R(k / 2048 if k < 2048 else (4096 - k) / 2048 if k < 6144 else (k - N) / 2048),
        tri(2), tri(4), tri(8),
        lambda k: R(k / N), lambda k: R(k / 4096 if k < 4096 else -(k - 4096) / 4096), saw(2), saw(4), saw(8),
        lambda k: F if k <= 4096 else -F,
        lambda k: F if k < 2730 else 0 if k < 5460 else -F,
        sqr(2), sqr(4), sqr(8),
        stair(2), stair(4), stair(8), lambda k: min(10, k * 11 // N) * 3264, stair(16),
        stair2(4), stair2(8), lambda k: S102[min(20, k * 21 // N)] * 128, stair2(16),
        lambda k: int(round(sp(k))) if k < 4096 else 1 - hu(sp(N - k)),                                      # Swapped Peak
        lambda k: R((k / 4096) ** 3) if k < 4096 else F if k == 4096 else -R(((N - k) / 4096) ** 3),
        lambda k: R((k / 4096) ** 6) if k < 4096 else 0 if k == 4096 else -R(((N - k) / 4096) ** 6),
        lambda k: alt(k) * int(round(32660.05 * (k / N) ** 1.5)),                                             # Ripple
        lambda k: alt(k) * R(half(k)),                                                                         # Grid
        lambda k: R(half(k)) if k < 4096 else int(round(16384 * sin(pi * (k - 4096) / 4096))),                # Cliff 1
        rmir, spiky, lambda k: st1[k], lambda k: st2[k]]
    assert len(defs) == len(GM_NAMES) == 66
    out = []
    for name, f in zip(GM_NAMES, defs):
        t = [f(k) for k in range(N)]
        assert all(-32768 <= v <= 32767 for v in t), name
        out.append((name, t))
    return out


def gen_shapes():
    sh = gm_shapes()
    rows = []
    for i, (name, t) in enumerate(sh):
        rows.append("    /* %d %s: %d..%d */\n" % (i, name, min(t), max(t)))
        for j in range(0, GM_N, 32):
            rows.append("    " + ",".join(str(v) for v in t[j:j + 32]) + ",\n")
    return ("/* Generated by tools/gen_vectors.py --shapes; do not edit. The 66 generic-macro shapes of 14 sec. A.6 in Macros.Mac\n"
            " * file order, OUR samples (+-32640 = 127.5 x 256): the sine family exactly round(32640 * sin), the others the authored\n"
            " * definitions in gen_vectors.py gm_shapes(). No Martin bytes: tools/ref/14-macros_mac_decode.py is used only by\n"
            " * --shapes --compare, on a developer PC, to measure each definition against the decode (docs/generated-files.md).\n"
            " * Regenerate: python -I tools/gen_vectors.py --shapes; verify: --shapes --check. */\n"
            '#include "engine/lj_shapes_gen.h"\n\n'
            "static const int16_t lj_gm_samples[%d * %d] = {\n" % (len(sh), GM_N) + "".join(rows) + "};\n\n"
            "const lj_gm_shapes lj_gm_shapes_builtin = { %d, %d, lj_gm_samples, {\n" % (len(sh), len(sh)) +
            "".join('    "%s",\n' % n for n, _ in sh) + "} };\n")


def shapes_compare():
    """Developer PC only: each definition against the decode of the user's / reference Macros.Mac (never emitted)."""
    path = os.environ.get("LJ4EVR_MACROS_MAC") or os.path.join(ROOT, "reference", "installer", "extracted_2.209", "app", "Macros.Mac")
    if not os.path.exists(path):
        print("gen_vectors --shapes --compare: no Macros.Mac at %s (set LJ4EVR_MACROS_MAC); skipped" % path)
        return 0
    recs = load("14-macros_mac_decode.py").decode(path)
    assert len(recs) == 66
    for i, ((name, t), (rname, _, rt)) in enumerate(zip(gm_shapes(), recs)):
        assert name == rname, (i, name, rname)
        d = [abs(a - b) for a, b in zip(t, rt)]
        print("%2d %-15s max |diff| %5d  samples differing %4d" % (i, name, max(d), sum(1 for x in d if x)))
    return 0


def shapes_main(check):
    if "--compare" in sys.argv:
        return shapes_compare()
    text = gen_shapes()
    rel = os.path.relpath(OUT_SHAPES, ROOT)
    if not check:
        with open(OUT_SHAPES, "w", encoding="ascii", newline="\n") as f:
            f.write(text)
        print("wrote %s (%d bytes)" % (rel, len(text)))
        return 0
    have = open(OUT_SHAPES, encoding="ascii", newline="").read() if os.path.exists(OUT_SHAPES) else None
    if have is not None and "--mutate" in sys.argv:                    # the failure row: flip sample 0 of '2*Sine' in the committed text
        j = have.index("\n", have.index("/* 0 2*Sine: ")) + 5
        have = have[:j] + ("1" if have[j] == "0" else "0") + have[j + 1:]
    if have != text:
        print("gen_vectors --shapes --check: %s differs from the generator output" % rel)
        return 1
    print("gen_vectors --shapes --check: %s up to date (66 shapes x %d samples)" % (rel, GM_N))
    return 0


# ---- W5 audio track (appended): --audio -> src/io/lj_audio_gen.c + tests/io/audio_vectors.h (W5-AUD-2; 05 s9.1) ----------
# The analyzer is integer only (hard rule 1): its 512-point FFT twiddles, the periodic Hann window, the 16 band edges and
# the Gain fader's dB table are computed here, never with <math.h> in the binary. The synthetic PCM of the test rows
# (a 1 kHz click, LCG noise, two bin-exact tones) is ours. Every number is a PROPOSAL rig W5-AUD-2 choice.
OUT_AUDIO = os.path.join(ROOT, "src", "io", "lj_audio_gen.c")
OUT_AUDIO_VEC = os.path.join(ROOT, "tests", "io", "audio_vectors.h")
AU_N, AU_RATE, AU_BANDS = 512, 44100, 16


def audio_tables():
    hann = [int(round(32767 * 0.5 * (1 - math.cos(2 * math.pi * i / AU_N)))) for i in range(AU_N)]
    cos = [int(round(32767 * math.cos(2 * math.pi * k / AU_N))) for k in range(AU_N // 2)]
    sin = [int(round(32767 * math.sin(2 * math.pi * k / AU_N))) for k in range(AU_N // 2)]
    edge = [1]
    for b in range(1, AU_BANDS + 1):                              # geometric over bins 1..256, at least one bin per band
        edge.append(max(edge[-1] + 1, int(round((AU_N // 2) ** (b / AU_BANDS)))))
    assert edge[-1] == AU_N // 2 and len(edge) == AU_BANDS + 1
    gain = [int(round(100 * 10 ** (p / 127.0))) for p in range(-127, 128)]   # fader -127..127 = -20..+20 dB, linear in dB
    assert gain[0] == 10 and gain[127] == 100 and gain[254] == 1000
    return hann, cos, sin, edge, gain


def audio_pcm():
    click = [int(round(24000 * math.sin(2 * math.pi * 1000 * i / AU_RATE) * (1 - i / 256.0))) for i in range(256)]
    x, noise = 12345, []
    for _ in range(AU_N):
        x = (x * 1103515245 + 12345) & 0x7FFFFFFF
        noise.append((x >> 16) % 1201 - 600)
    low = [int(round(16000 * math.sin(2 * math.pi * 2 * i / AU_N))) for i in range(AU_N)]     # bin 2 = 172 Hz, band 1
    high = [int(round(16000 * math.sin(2 * math.pi * 64 * i / AU_N))) for i in range(AU_N)]   # bin 64 = 5.5 kHz, band 12
    return click, noise, low, high


def gen_audio():
    hann, cos, sin, edge, gain = audio_tables()
    head = ("/* Generated by tools/gen_vectors.py --audio; do not edit. The Audio Analyzer's integer tables (io/lj_audio.h,\n"
            " * W5-AUD-2): Q15 periodic Hann window and FFT twiddles for N = %d, the 16 band edges (FFT bins, geometric over\n"
            " * 1..256), the Gain fader table (-127..127 = -20..+20 dB as a percentage). Ours, PROPOSAL rig W5-AUD-2.\n"
            " * Regenerate: python -I tools/gen_vectors.py --audio; verify: --audio --check. */\n"
            '#include "io/lj_audio.h"\n\n' % AU_N)
    return (head +
            "const int16_t lj_audio_hann[LJ_AUDIO_BLOCK] = {\n%s\n};\n" % c_rows(hann) +
            "const int16_t lj_audio_cos[LJ_AUDIO_BLOCK / 2] = {\n%s\n};\n" % c_rows(cos) +
            "const int16_t lj_audio_sin[LJ_AUDIO_BLOCK / 2] = {\n%s\n};\n" % c_rows(sin) +
            "const uint16_t lj_audio_band_edge[LJ_AUDIO_BANDS + 1] = { %s };\n" % ", ".join(str(v) for v in edge) +
            "const uint16_t lj_audio_gain_pct[255] = {\n%s\n};\n" % c_rows(gain))


def gen_audio_vectors():
    click, noise, low, high = audio_pcm()
    return ("/* Generated by tools/gen_vectors.py --audio; do not edit. Synthetic PCM for tests/io/test_audio.c (W5-AUD-2):\n"
            " * a 256-sample 1 kHz click with a linear decay (peak 24000), 512 samples of LCG noise in -600..600, and two\n"
            " * bin-exact 16000-amplitude tones (bin 2 = 172 Hz, bin 64 = 5.5 kHz) at 44100 Hz. Ours, no recording. */\n"
            "#ifndef LJ_TESTS_IO_AUDIO_VECTORS_H\n#define LJ_TESTS_IO_AUDIO_VECTORS_H\n\n#include <stdint.h>\n\n"
            "static const int16_t lj_av_click[256] = {\n%s\n};\n" % c_rows(click) +
            "static const int16_t lj_av_noise[512] = {\n%s\n};\n" % c_rows(noise) +
            "static const int16_t lj_av_low[512] = {\n%s\n};\n" % c_rows(low) +
            "static const int16_t lj_av_high[512] = {\n%s\n};\n" % c_rows(high) +
            "\n#endif /* LJ_TESTS_IO_AUDIO_VECTORS_H */\n")


def audio_main(check):
    rc = 0
    for path, text in ((OUT_AUDIO, gen_audio()), (OUT_AUDIO_VEC, gen_audio_vectors())):
        rel = os.path.relpath(path, ROOT)
        have = open(path, encoding="ascii", newline="").read() if os.path.exists(path) else None
        if check:
            if have != text:
                print("gen_vectors --audio --check: %s differs from the generator output" % rel)
                rc = 1
            else:
                print("gen_vectors --audio --check: %s up to date" % rel)
        else:
            with open(path, "w", encoding="ascii", newline="\n") as f:
                f.write(text)
            print("wrote %s (%d bytes)" % (rel, len(text)))
    return rc


# ---- W5 dmxin track (appended): --vtr -> src/io/lj_vtr_gen.c (W5-DMXIN-7; note 05 s3.3) ------------------------------
# The eight SYSTEM value tables LJ2 installs under User\ValueTables, regenerated from their mappings (DMX tables are facts,
# D2), never copied: each is a rule below, or (Sine, whose curve has no closed form we found; the nearest raised-cosine
# misses 57 entries) its 255 steps as a digit string. IDs, TYPE and NAME are the identifying facts (a table copied into an
# LJ2 assignment keeps its ID); PURPOSE is our text (authored prose does not ship, the ME-137 test). --vtr --compare (developer
# PC, reference tree present) checks every map equals LJ2's and that no file we would write is byte-equal to LJ2's.
OUT_VTR = os.path.join(ROOT, "src", "io", "lj_vtr_gen.c")
VTR_SINE_STEPS = ("00000000010000010000100100010100100101010101010110101101101101110111011111011111111110111111111211111111112111"
                  "11121111211121112111211121121121121121121121211211212112112121121211212112112121121121211211211211211211211121"
                  "11211121111211112111111121111111111")


def vtr_tables():
    sine = [0]
    for c in VTR_SINE_STEPS:
        sine.append(sine[-1] + int(c))
    assert len(sine) == 256 and sine[-1] == 255
    skips = (38, 100, 163, 225, 255)          # Off/on, disable treshold: 0 below 6, then one step per value, two at these inputs
    return [
        ("{76A2BE02-AD9C-4BE4-B4CA-7419AD2BBB52}", "Linear", "1:1, no translation", list(range(256))),
        ("{96817479-F2BE-40A9-B9B9-58FE315306F6}", "Linear inverted", "Reversed 1:1",
         [255 - i for i in range(128)] + [127] + [256 - i for i in range(129, 256)]),
        ("{FC78008E-C9B8-4A92-B204-AF8D693CC6A6}", "Off/on, disable treshold", "0 below input 6, then rising to full",
         [0 if i < 6 else i - 5 + sum(1 for s in skips if s <= i) for i in range(256)]),
        ("{CF413860-C82A-4ADF-AB05-211134196506}", "Off/On", "0 below half, full from half", [0 if i < 128 else 255 for i in range(256)]),
        ("{09392EEE-8914-403E-9159-B9B80D2E1617}", "On/Off", "Full below half, 0 from half", [255 if i < 128 else 0 for i in range(256)]),
        ("{450873ED-828C-4529-B994-7EA754FE0E28}", "Sine", "Slow start, fast finish", sine),
        ("{813B4C9E-E37D-4598-97E1-BD4B70960E31}", "Sine inverted", "Reversed quarter sine",
         [math.ceil(255 * (1 - math.sin(math.pi / 2 * i / 255)) - 0.5 - 1e-9) for i in range(256)]),   # round half down (i = 85 is 127.5)
        ("{9B3EA976-8C53-4173-91A8-774C8F881E3D}", "Sqrt", "Square-root curve", [int(math.floor(math.sqrt(255 * i) + 0.5)) for i in range(256)]),
    ]


def vtr_file_text(t):
    gid, name, purpose, m = t
    return ("// LightJockey DMX value translation file\r\nID=%s\r\nTYPE=SYSTEM\r\nNAME=%s\r\nPURPOSE=%s\r\n" % (gid, name, purpose)
            + "".join("%d=%d\r\n" % (i, v) for i, v in enumerate(m)))


def gen_vtr():
    ts = vtr_tables()
    for _, _, _, m in ts:
        assert len(m) == 256 and all(0 <= v <= 255 for v in m)
    return ("/* Generated by tools/gen_vectors.py --vtr; do not edit. The SYSTEM DMX-in value tables (io/lj_dmxin.h, W5-DMXIN-7),\n"
            " * regenerated from their mappings (rules and a step string in the generator), never copied. PURPOSE texts are ours.\n"
            " * Regenerate: python -I tools/gen_vectors.py --vtr; verify: --vtr --check; developer PC: --vtr --compare. */\n"
            '#include "io/lj_dmxin.h"\n\n'
            "const uint8_t lj_vtr_stock_map[LJ_VTR_STOCK][256] = {\n"
            + "".join("    { /* %s */\n%s\n    },\n" % (n, c_rows(m)) for _, n, _, m in ts) + "};\n"
            "const char *const lj_vtr_stock_text[LJ_VTR_STOCK][3] = {\n"
            + "".join('    { "%s", "%s", "%s" },\n' % (g, n, p) for g, n, p, _ in ts) + "};\n")


def vtr_compare():
    import glob, hashlib
    ref = os.environ.get("LJ4EVR_REFERENCE_DIR") or os.path.join(ROOT, "reference")
    d = os.path.join(ref, "installer", "extracted_2.209", "app", "User", "ValueTables")
    if not os.path.isdir(d):
        print("gen_vectors --vtr --compare: no reference ValueTables at %s; skipped" % d)
        return 0
    rc, ref_hashes = 0, {}
    for f in glob.glob(os.path.join(d, "*.vtr")):
        b = open(f, "rb").read()
        ref_hashes[hashlib.sha1(b).hexdigest()] = os.path.basename(f)
    for t in vtr_tables():
        f = glob.glob(os.path.join(d, "SYSTEM_*%s.vtr" % t[0]))
        if len(f) != 1:
            print("%-26s no reference file" % t[1]); rc = 1; continue
        m = {}
        for line in open(f[0], encoding="cp1252").read().splitlines():
            k, _, v = line.partition("=")
            if k.isdigit():
                m[int(k)] = int(v)
        same = [m.get(i, i) for i in range(256)] == t[3]
        hit = hashlib.sha1(vtr_file_text(t).encode("cp1252")).hexdigest() in ref_hashes
        print("%-26s map %s, file hash %s" % (t[1], "equal" if same else "DIFFERS", "EQUAL (fail)" if hit else "differs"))
        rc |= (not same) or hit
    print("gen_vectors --vtr --compare: %s" % ("FAIL" if rc else "8 maps equal LJ2's, 0 equal file hashes"))
    return 1 if rc else 0


def vtr_main(check):
    if "--compare" in sys.argv:
        return vtr_compare()
    text = gen_vtr()
    rel = os.path.relpath(OUT_VTR, ROOT)
    if not check:
        with open(OUT_VTR, "w", encoding="ascii", newline="\n") as f:
            f.write(text)
        print("wrote %s (%d bytes)" % (rel, len(text)))
        return 0
    have = open(OUT_VTR, encoding="ascii", newline="").read() if os.path.exists(OUT_VTR) else None
    if have != text:
        print("gen_vectors --vtr --check: %s differs from the generator output" % rel)
        return 1
    print("gen_vectors --vtr --check: %s up to date" % rel)
    return 0


if __name__ == "__main__":
    sys.exit(main())
